/**
 * Chooses light, dark or the system's mode (`design/components/mode-switch.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/mode-switch.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  BORROWED,
  IDENTITY,
  agentMember,
  claimSlot,
  createDerived,
  provide,
  scope,
  setMode,
  useMode,
  type BorrowedHolder,
  type Defaults,
} from '@polymorph/solid'
import SegmentedControl from './SegmentedControl'

export interface ModeSwitchMessages {
  /** The segment that pins the light mode: "Light". */
  light: string
  /** The segment that pins the dark mode: "Dark". */
  dark: string
  /** The segment that follows the operating system's mode: "System". */
  system: string
}

export interface ModeSwitchProps {
  disabled?: boolean
  /**
   * The group's accessible name ("Appearance"), because outside a form no FormField names it.
   */
  label: string
  /**
   * Omit for the English defaults; a localized application passes every key.
   */
  messages?: ModeSwitchMessages
  /**
   * The reader's choice. Uncontrolled, it is called after the mode is set.
   */
  onChange?: (value: 'light' | 'dark' | 'system') => void
  /**
   * SegmentedControl's sizes: it sits in a toolbar, a menu's header or a settings row.
   */
  size?: 'sm' | 'md'
  /**
   * The choice shown, while the application holds it. With it, a choice calls `onChange` and
   * sets no mode. Without it, the ModeSwitch shows the document's preference and sets the mode.
   */
  value?: 'light' | 'dark' | 'system'
}

/** Chooses light, dark or the system's mode. */
export default function ModeSwitch(given: ModeSwitchProps): JSX.Element {
  const props = mergeProps(
    {
      messages: (() => ({ light: 'Light', dark: 'Dark', system: 'System' }))(),
      size: 'md',
      disabled: false,
    } as Defaults<ModeSwitchProps, 'messages' | 'size' | 'disabled'>,
    claimSlot(given),
  )
  return scope(() => {
    provide(IDENTITY, 'mode-switch')
    const borrowed: BorrowedHolder = {}
    provide(BORROWED, borrowed)
    const runtime = useMode()
    const options = createDerived(() => [
      { value: 'light', label: props.messages.light, icon: 'mode-light' as const },
      { value: 'dark', label: props.messages.dark, icon: 'mode-dark' as const },
      { value: 'system', label: props.messages.system, icon: 'mode-system' as const },
    ])
    const shown = createDerived(() => props.value ?? runtime().preference)
    const choose = createDerived(() => (next: string): void => {
      const picked = next === 'light' || next === 'dark' ? next : 'system'
      if (props.value === undefined) setMode(picked)
      props.onChange?.(picked)
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'ModeSwitch',
        element: () => borrowed.element?.(),
        state: () => ({
          value: shown.value,
          options: options.value.map((option) => ({ id: option.value, label: option.label })),
          disabled: props.disabled,
        }),
        actions: {
          choose: { argument: 'id', run: (value) => value !== shown.value && choose.value(value) },
        },
        withholds: () => borrowed.element?.(),
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <SegmentedControl
        options={options.value}
        value={shown.value}
        label={props.label}
        size={props.size}
        disabled={props.disabled}
        onChange={($event) => choose.value($event)}
      />
    )
  })
}
